class Solution {
public:
    int countStudents(vector<int>& students, vector<int>& sandwiches) {
        queue<int> q;
        for (int s : students) q.push(s);
        int top = 0, misses = 0;
        while (!q.empty() && misses < (int)q.size()) {
            int s = q.front();
            q.pop();
            if (s == sandwiches[top]) {
                top++;
                misses = 0;
            } else {
                q.push(s);
                misses++;
            }
        }
        return q.size();
    }
};
